cd /Users/michelkerkmeester/worktrees/public/315-frontend-reference-restructure && python3 - <<'PY'
import subprocess,re
files=[l.strip() for l in subprocess.check_output(['git','diff','--name-only','--','.skilled/skills/system-spec-kit'],text=True).splitlines() if l.strip()]
pats={
 'specpath': re.compile(r'specs/\d{3}'),
 'phase': re.compile(r'\bphase\s+\d{3}\b', re.I),
 'packet': re.compile(r'\b(0\d\d|1\d\d)-\w[\w-]*'),
 'postnum': re.compile(r'\b(post|after)[-_ ]?\d{2,3}\b', re.I),
 'todo': re.compile(r'\b(TODO|WIP|TBD)\b'),
 'taskid': re.compile(r'\b[A-Z]-[A-Z]{2,4}-[A-Z]{2,4}-\d{2}\b'),
}
for f in files:
    s=open(f).read()
    out=[]; infence=False
    for i,line in enumerate(s.splitlines(),1):
        if line.lstrip().startswith('```'):
            infence=not infence; continue
        if infence: continue
        for name,p in pats.items():
            if p.search(line):
                out.append((i,name,line.strip()[:160]))
    if out:
        print('##',f)
        for i,n,l in out: print(f'  {i} {n}: {l}')
PY

